42	/// A migration identity-leg operation, built and signed locally, ready to submit.
43	///
44	/// Mirrors `SignedRecoveryOp` from `recovery.rs`: the `diff` drives the review /
45	/// biometric-approval UI, and `signed_op` is the JSON POSTed to plc.directory.
46	#[derive(Debug, Serialize, Clone)]
47	#[serde(rename_all = "camelCase")]
48	pub struct SignedMigrationOp {
49	    /// Human-readable diff of what the migration op changes (endpoint + key swap).
50	    pub diff: OpDiff,
51	    /// The signed PLC operation JSON, ready to POST to plc.directory.
52	    pub signed_op: serde_json::Value,
53	}
