77	fn multibase(key: &str) -> &str {
78	    key.strip_prefix("did:key:").unwrap_or(key)
79	}
80	
81	fn did_web_url(did: &str) -> Result<String, MigrateError> {
82	    let host = did
83	        .strip_prefix("did:web:")
84	        .ok_or(MigrateError::GuardRejected {
85	            reason: "identity is not did:web".into(),
86	        })?;
87	    if host.contains(':') || host.contains('/') || host.is_empty() {
88	        return Err(MigrateError::GuardRejected {
89	            reason: "only hostname-form did:web identities are supported".into(),
90	        });
91	    }
92	    Ok(format!(
93	        "https://{}/.well-known/did.json",
94	        host.to_ascii_lowercase()
95	    ))
96	}
