98	#[tauri::command]
99	/// Compose the exact did:web document that the user must review and publish for migration.
100	pub async fn build_did_web_migration_document_cmd(
101	    state: tauri::State<'_, crate::oauth::AppState>,
102	    did: String,
103	) -> Result<DidWebMigrationDocument, MigrateError> {
104	    let dest_client = {
105	        let guard = state.migration_state.lock().await;
106	        let migration = guard
107	            .as_ref()
108	            .ok_or_else(|| MigrateError::IdentityNotFound {
109	                message: "no identity leg is armed".into(),
110	            })?;
111	        if migration.did != did || !did.starts_with("did:web:") {
112	            return Err(MigrateError::IdentityNotFound {
113	                message: "DID mismatch".into(),
114	            });
115	        }
116	        migration.dest_oauth_client.clone()
117	    };
118	    let (_, current) =
119	        state
120	            .pds_client()
121	            .discover_pds(&did)
122	            .await
123	            .map_err(|e| MigrateError::NetworkError {
124	                message: e.to_string(),
125	            })?;
126	    let recommended = get_recommended_did_credentials(&dest_client)
127	        .await
128	        .map_err(|e| MigrateError::NetworkError {
129	            message: e.to_string(),
130	        })?;
131	    let repo_key = recommended
132	        .verification_methods
133	        .as_ref()
134	        .and_then(|value| value.get(ATPROTO_VERIFICATION_METHOD_ID))
135	        .and_then(serde_json::Value::as_str)
136	        .ok_or_else(|| MigrateError::InvalidRecommendedCredentials {
137	            message: "missing verificationMethods.atproto".into(),
138	        })?
139	        .to_string();
140	    let pds_endpoint = recommended
141	        .services
142	        .as_ref()
143	        .and_then(|value| value.get(ATPROTO_PDS_SERVICE_ID))
144	        .and_then(|value| value.get("endpoint"))
145	        .and_then(serde_json::Value::as_str)
146	        .ok_or_else(|| MigrateError::InvalidRecommendedCredentials {
147	            message: "missing services.atproto_pds.endpoint".into(),
148	        })?
149	        .to_string();
150	    let device = crate::device_key::get_or_create().map_err(|e| MigrateError::SigningFailed {
151	        message: e.to_string(),
152	    })?;
153	
154	    let mut methods = Vec::new();
155	    if let Some(existing) = current.verification_methods.as_object() {
156	        for (name, value) in existing {
157	            if name != ATPROTO_VERIFICATION_METHOD_ID {
158	                if let Some(key) = value.as_str() {
159	                    methods.push(serde_json::json!({
160	                        "id": format!("{did}#{name}"), "type": "Multikey", "controller": did,
161	                        "publicKeyMultibase": multibase(key)
162	                    }));
163	                }
164	            }
165	        }
166	    }
167	    methods.retain(|method| {
168	        method.get("id").and_then(serde_json::Value::as_str) != Some(&format!("{did}#device"))
169	    });
170	    methods.push(serde_json::json!({"id": format!("{did}#device"), "type": "Multikey", "controller": did, "publicKeyMultibase": device.multibase}));
171	    methods.push(serde_json::json!({"id": format!("{did}#atproto"), "type": "Multikey", "controller": did, "publicKeyMultibase": multibase(&repo_key)}));
172	    let document = serde_json::json!({
173	        "@context": ["https://www.w3.org/ns/did/v1"],
174	        "id": did,
175	        // Domain migration must never let destination recommendations change the user's handle.
176	        "alsoKnownAs": current.also_known_as,
177	        "verificationMethod": methods,
178	        "service": [{"id": format!("{did}#atproto_pds"), "type": "AtprotoPersonalDataServer", "serviceEndpoint": pds_endpoint}],
179	    });
180	    let document_text = format!(
181	        "{}\n",
182	        serde_json::to_string_pretty(&document).map_err(|e| MigrateError::SigningFailed {
183	            message: e.to_string(),
184	        })?
185	    );
186	    Ok(DidWebMigrationDocument {
187	        document_text,
188	        device_key: format!("{did}#device"),
189	        repo_key: format!("{did}#atproto"),
190	        pds_endpoint,
191	    })
192	}
