194	#[tauri::command]
195	/// Verify the reviewed bytes are authoritative, refresh the destination, and adopt the identity.
196	pub async fn submit_did_web_migration_document_cmd(
197	    state: tauri::State<'_, crate::oauth::AppState>,
198	    did: String,
199	    document_text: String,
200	    enable_managed_hosting: bool,
201	) -> Result<ClaimResult, MigrateError> {
202	    let dest_client = {
203	        let guard = state.migration_state.lock().await;
204	        let migration = guard
205	            .as_ref()
206	            .ok_or_else(|| MigrateError::IdentityNotFound {
207	                message: "no identity leg is armed".into(),
208	            })?;
209	        if migration.did != did {
210	            return Err(MigrateError::IdentityNotFound {
211	                message: "DID mismatch".into(),
212	            });
213	        }
214	        migration.dest_oauth_client.clone()
215	    };
216	    let live = state
217	        .pds_client()
218	        .client()
219	        .get(did_web_url(&did)?)
220	        .send()
221	        .await
222	        .and_then(reqwest::Response::error_for_status)
223	        .map_err(|e| MigrateError::NetworkError {
224	            message: e.to_string(),
225	        })?
226	        .text()
227	        .await
228	        .map_err(|e| MigrateError::NetworkError {
229	            message: e.to_string(),
230	        })?;
231	    if live.as_bytes() != document_text.as_bytes() {
232	        return Err(MigrateError::GuardRejected {
233	            reason: "published did.json does not match the reviewed bytes".into(),
234	        });
235	    }
236	    let refreshed = dest_client
237	        .post(
238	            "/xrpc/com.atproto.identity.refreshIdentity",
239	            &serde_json::json!({ "identifier": did }),
240	        )
241	        .await
242	        .map_err(|e| MigrateError::NetworkError {
243	            message: e.to_string(),
244	        })?;
245	    if !refreshed.status().is_success() {
246	        return Err(MigrateError::NetworkError {
247	            message: "destination did not accept the published document".into(),
248	        });
249	    }
250	    if enable_managed_hosting {
251	        let result = dest_client
252	            .post("/v1/did-web/hosting", &serde_json::json!({"enabled": true}))
253	            .await;
254	        match result {
255	            Ok(response) if response.status().is_success() => {}
256	            Ok(response) => {
257	                tracing::warn!(status = %response.status(), did = %did, "migration verified, but optional managed hosting was not enabled")
258	            }
259	            Err(error) => {
260	                tracing::warn!(error = %error, did = %did, "migration verified, but optional managed hosting was unreachable")
261	            }
262	        }
263	    }
264	    let updated_did_doc: serde_json::Value =
265	        serde_json::from_str(&document_text).map_err(|e| MigrateError::GuardRejected {
266	            reason: format!("reviewed did.json is invalid: {e}"),
267	        })?;
268	    let store = IdentityStore;
269	    if let Err(e) = store.add_identity(&did) {
270	        if !matches!(
271	            e,
272	            crate::identity_store::IdentityStoreError::IdentityAlreadyExists
273	        ) {
274	            return Err(MigrateError::IdentityNotFound {
275	                message: e.to_string(),
276	            });
277	        }
278	    }
279	    store
280	        .adopt_global_device_key(&did)
281	        .map_err(|e| MigrateError::IdentityNotFound {
282	            message: e.to_string(),
283	        })?;
284	    store
285	        .store_did_doc(&did, &document_text)
286	        .map_err(|e| MigrateError::IdentityNotFound {
287	            message: e.to_string(),
288	        })?;
289	    // Keep the armed leg available until every retryable local write has completed.
290	    *state.migration_state.lock().await = None;
291	    Ok(ClaimResult { updated_did_doc })
292	}
