295	#[derive(Debug, Serialize, thiserror::Error)]
296	#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE")]
297	pub enum MigrateError {
298	    /// The wallet does not hold an authorized key in the DID's current rotationKeys,
299	    /// so it cannot self-sign. The orchestrator must fall back to the interop path.
300	    #[error("Wallet is not authorized to self-sign for this DID (no device key in current rotationKeys)")]
301	    WalletNotAuthorized,
302	    /// The strict pre-sign allowlist rejected the proposed operation.
303	    #[error("Migration operation rejected by pre-sign guard: {reason}")]
304	    GuardRejected { reason: String },
305	    /// The destination PDS's recommended credentials were missing or malformed.
306	    #[error("Invalid recommended credentials from destination PDS: {message}")]
307	    InvalidRecommendedCredentials { message: String },
308	    /// The audit log could not be parsed or contained no usable current state.
309	    #[error("Invalid audit log: {message}")]
310	    InvalidAuditLog { message: String },
311	    /// Local signing failed.
312	    #[error("Signing failed: {message}")]
313	    SigningFailed { message: String },
314	    /// plc.directory rejected the submitted operation.
315	    #[error("PLC directory error: {message}")]
316	    PlcDirectoryError { message: String },
317	    /// A network call failed.
318	    #[error("Network error: {message}")]
319	    NetworkError { message: String },
320	    /// The DID's device key could not be found/created.
321	    #[error("Identity not found: {message}")]
322	    IdentityNotFound { message: String },
323	    /// No pending migration (build must run before submit), or DID mismatch.
324	    #[error("Migration not ready: {message}")]
325	    MigrationNotReady { message: String },
326	}
