331	pub enum MigrationPath {
332	    /// The wallet holds an authorized rotation key and can self-sign the PLC op.
333	    SelfSigned,
334	    /// The wallet does not hold an authorized rotation key; use the PDS-signed interop path.
335	    Interop,
