353	// ── Pure inputs to the guard ─────────────────────────────────────────────────
354	
355	/// The facts the strict pre-sign guard needs to decide whether a proposed migration
356	/// operation is safe to sign. Deliberately flattened to plain strings/vecs so the
357	/// guard is a pure, trivially testable function.
358	#[derive(Debug, Clone)]
359	pub struct MigrationInputs {
360	    /// The wallet's per-DID device key (`did:key:z...`). Must remain at rotationKeys[0].
361	    pub device_key_id: String,
362	    /// The DID's CURRENT rotation keys (from the latest audit-log op).
363	    pub current_rotation_keys: Vec<String>,
364	    /// The DID's CURRENT alsoKnownAs (handle URIs) — a migration must preserve these.
365	    pub current_also_known_as: Vec<String>,
366	    /// The rotation keys the DESTINATION PDS recommended — the allowlist for keys
367	    /// permitted beyond the device key at [0].
368	    pub recommended_rotation_keys: Vec<String>,
369	    /// The rotation keys we intend to put in the op (device key at [0] + recommended).
370	    pub proposed_rotation_keys: Vec<String>,
371	    /// The alsoKnownAs we intend to put in the op.
372	    pub proposed_also_known_as: Vec<String>,
373	    /// The service ids we intend to put in the op's `services` map.
374	    pub proposed_service_ids: Vec<String>,
375	}
376	
377	// ── The strict pre-sign guard (STRICT ALLOWLIST) ─────────────────────────────
378	
379	/// Reject the proposed migration operation unless it satisfies the strict allowlist.
380	///
381	/// This is the security core of the self-signed migration leg. The device key can
382	/// technically sign anything, so safety comes entirely from validating the INPUTS
383	/// before a signature is ever produced. The policy is a strict allowlist: the op must
384	/// make ONLY the changes a migration is supposed to make, and nothing else, or we
385	/// abort.
386	///
387	/// Return `Ok(())` if every rule holds. Otherwise return the most specific error:
388	/// - `MigrateError::WalletNotAuthorized` when the wallet holds no authorized key for
389	///   the DID (device key is not among `current_rotation_keys`) — the caller will
390	///   defer to the PDS-signed interop path.
391	/// - `MigrateError::GuardRejected { reason }` for any other violation, with a short
392	///   human-readable `reason`.
393	///
394	/// The rules the strict allowlist must enforce:
395	///  1. Sovereignty: `proposed_rotation_keys[0]` equals `device_key_id`.
396	///  2. Authorization: `device_key_id` is present in `current_rotation_keys`
397	///     (otherwise → `WalletNotAuthorized`).
398	///  3. Key allowlist: every proposed rotation key AFTER index 0 appears in
399	///     `recommended_rotation_keys` (no smuggled keys).
400	///  4. Handle preservation: `proposed_also_known_as` equals `current_also_known_as`.
401	///  5. Service allowlist: the proposed op touches ONLY the atproto PDS service —
402	///     `proposed_service_ids` is exactly `[ATPROTO_PDS_SERVICE_ID]`.
403	pub fn guard_migration_op(inputs: &MigrationInputs) -> Result<(), MigrateError> {
404	    // Rule 2 (authorization): the wallet must currently hold an authorized key for
405	    // this DID, or it cannot self-sign — the caller falls back to the interop path.
406	    // Checked first so the distinct `WalletNotAuthorized` signal wins over any
407	    // proposed-op quibble.
408	    if !inputs.current_rotation_keys.contains(&inputs.device_key_id) {
409	        return Err(MigrateError::WalletNotAuthorized);
410	    }
411	
412	    // Rule 1 (sovereignty): the device key must remain at rotationKeys[0].
413	    if inputs.proposed_rotation_keys.first() != Some(&inputs.device_key_id) {
414	        return Err(MigrateError::GuardRejected {
415	            reason: format!(
416	                "device key must be rotationKeys[0]; found {:?}",
417	                inputs.proposed_rotation_keys.first()
418	            ),
419	        });
420	    }
421	
422	    // Rule 3 (key allowlist): every proposed rotation key after [0] must be one the
423	    // destination recommended — no smuggled keys.
424	    for key in inputs.proposed_rotation_keys.iter().skip(1) {
425	        if !inputs.recommended_rotation_keys.contains(key) {
426	            return Err(MigrateError::GuardRejected {
427	                reason: format!("rotation key not recommended by destination: {key}"),
428	            });
429	        }
430	    }
431	
432	    // Rule 4 (handle preservation): a migration must not alter alsoKnownAs.
433	    if inputs.proposed_also_known_as != inputs.current_also_known_as {
434	        return Err(MigrateError::GuardRejected {
435	            reason: "alsoKnownAs (handle) must be preserved across migration".to_string(),
436	        });
437	    }
438	
439	    // Rule 5 (service allowlist): the op may touch only the atproto PDS service.
440	    if inputs.proposed_service_ids.len() != 1
441	        || inputs.proposed_service_ids.first().map(String::as_str) != Some(ATPROTO_PDS_SERVICE_ID)
442	    {
443	        return Err(MigrateError::GuardRejected {
444	            reason: format!(
445	                "migration may only set the '{ATPROTO_PDS_SERVICE_ID}' service; found {:?}",
446	                inputs.proposed_service_ids
447	            ),
448	        });
449	    }
450	
451	    Ok(())
452	}
