454	// ── Current-state extraction from the audit log ──────────────────────────────
455	
456	/// The slice of current DID state the migration build needs, derived from the latest
457	/// non-nullified audit-log operation.
458	#[derive(Debug, Clone)]
459	pub(crate) struct CurrentState {
460	    /// CID of the latest op — becomes the new op's `prev`.
461	    pub prev_cid: String,
462	    /// Current rotation keys (for authorization + diff).
463	    pub rotation_keys: Vec<String>,
464	    /// Current alsoKnownAs (preserved into the new op).
465	    pub also_known_as: Vec<String>,
466	    /// Current atproto_pds endpoint, if present (for the diff's `old_endpoint`).
467	    pub pds_endpoint: Option<String>,
468	}
469	
470	/// Read the resulting DID state from the latest non-nullified audit-log entry.
471	///
472	/// A PLC operation's JSON encodes the DID's state AFTER it is applied, so the newest
473	/// entry's `operation` object is the current state. We read fields defensively; an
474	/// empty log or a missing `prev`-able CID is an error (a genesis-only DID that the
475	/// wallet controls still has a CID to chain against).
476	pub(crate) fn latest_op_state(audit_log: &[AuditEntry]) -> Result<CurrentState, MigrateError> {
477	    let latest = audit_log
478	        .iter()
479	        .rev()
480	        .find(|e| !e.nullified)
481	        .ok_or_else(|| MigrateError::InvalidAuditLog {
482	            message: "audit log is empty or fully nullified".to_string(),
483	        })?;
484	
485	    let op = &latest.operation;
486	
487	    // Parse the required arrays strictly: a malformed or missing `rotationKeys` /
488	    // `alsoKnownAs` must be an error, never a silently-truncated `[]`. Truncating
489	    // `alsoKnownAs` to `[]` would let the build "preserve" an empty handle set and
490	    // sign a handle-removing op that the guard's `proposed == current` check misses.
491	    let rotation_keys = string_array_field(op, "rotationKeys")?;
492	    if rotation_keys.is_empty() {
493	        return Err(MigrateError::InvalidAuditLog {
494	            message: "operation.rotationKeys is empty".to_string(),
495	        });
496	    }
497	    let also_known_as = string_array_field(op, "alsoKnownAs")?;
498	
499	    let pds_endpoint = op
500	        .get("services")
501	        .and_then(|s| s.get(ATPROTO_PDS_SERVICE_ID))
502	        .and_then(|svc| svc.get("endpoint"))
503	        .and_then(|e| e.as_str())
504	        .map(String::from);
505	
506	    Ok(CurrentState {
507	        prev_cid: latest.cid.clone(),
508	        rotation_keys,
509	        also_known_as,
510	        pds_endpoint,
511	    })
512	}
513	
514	/// Parse a required string-array field from a PLC operation, rejecting a missing
515	/// field, a non-array value, or any non-string element. This keeps malformed
516	/// audit-log state from being silently coerced into a value we would then sign.
517	fn string_array_field(op: &serde_json::Value, field: &str) -> Result<Vec<String>, MigrateError> {
518	    let arr =
519	        op.get(field)
520	            .and_then(|v| v.as_array())
521	            .ok_or_else(|| MigrateError::InvalidAuditLog {
522	                message: format!("operation.{field} is missing or not an array"),
523	            })?;
524	
525	    arr.iter()
526	        .enumerate()
527	        .map(|(idx, value)| {
528	            value
529	                .as_str()
530	                .map(String::from)
531	                .ok_or_else(|| MigrateError::InvalidAuditLog {
532	                    message: format!("operation.{field}[{idx}] is not a string"),
533	                })
534	        })
535	        .collect()
536	}
