538	/// Read current rotation keys from the latest non-nullified PLC audit-log entry.
539	///
540	/// Unlike `pds_client::rotation_keys_from_audit_log`, this helper is strict: malformed
541	/// logs are an error so path detection can fail closed as `CannotDetermine` instead
542	/// of silently picking the interop path from an accidental empty key set.
543	pub(crate) fn current_rotation_keys_from_audit_log(
544	    raw_json: &str,
545	) -> Result<Vec<String>, MigrateError> {
546	    let audit_log =
547	        crypto::parse_audit_log(raw_json).map_err(|e| MigrateError::InvalidAuditLog {
548	            message: format!("failed to parse audit log: {e}"),
549	        })?;
550	    let latest = audit_log
551	        .iter()
552	        .rev()
553	        .find(|e| !e.nullified)
554	        .ok_or_else(|| MigrateError::InvalidAuditLog {
555	            message: "audit log is empty or fully nullified".to_string(),
556	        })?;
557	    let rotation_keys = string_array_field(&latest.operation, "rotationKeys")?;
558	    if rotation_keys.is_empty() {
559	        return Err(MigrateError::InvalidAuditLog {
560	            message: "operation.rotationKeys is empty".to_string(),
561	        });
562	    }
563	    Ok(rotation_keys)
564	}
