566	/// Decide whether the wallet can self-sign a migration for this DID.
567	///
568	/// The detector encodes ADR-0002's two-path model: if the wallet's per-DID device
569	/// key appears anywhere in the current rotationKeys, the wallet can use the
570	/// self-signed path; otherwise it must fall back to the PDS-signed interop path.
571	/// A key at index 1+ is still authorized, but the index is surfaced so the UI can
572	/// explain that the wallet is not the primary rotation key.
573	pub(crate) fn decide_migration_path(
574	    rotation_keys: &[String],
575	    device_key_id: Option<&str>,
576	) -> MigrationPathDecision {
577	    let Some(device_key_id) = device_key_id else {
578	        return MigrationPathDecision {
579	            path: MigrationPath::Interop,
580	            device_key_id: None,
581	            rotation_key_index: None,
582	            reason: "wallet has no device key for this DID; use PDS-signed interop".to_string(),
583	        };
584	    };
585	
586	    match rotation_keys.iter().position(|key| key == device_key_id) {
587	        Some(index) => MigrationPathDecision {
588	            path: MigrationPath::SelfSigned,
589	            device_key_id: Some(device_key_id.to_string()),
590	            rotation_key_index: Some(index),
591	            reason: if index == 0 {
592	                "wallet device key is the primary rotation key; self-signed migration is available"
593	                    .to_string()
594	            } else {
595	                format!(
596	                    "wallet device key is authorized at rotationKeys[{index}]; self-signed migration is available"
597	                )
598	            },
599	        },
600	        None => MigrationPathDecision {
601	            path: MigrationPath::Interop,
602	            device_key_id: Some(device_key_id.to_string()),
603	            rotation_key_index: None,
604	            reason: "wallet device key is not in current rotationKeys; use PDS-signed interop"
605	                .to_string(),
606	        },
607	    }
608	}
