610	/// Fetch current PLC state and decide which migration path should be used.
611	pub async fn detect_migration_path(pds_client: &PdsClient, did: &str) -> MigrationPathDecision {
612	    let log_json = match pds_client.fetch_audit_log(did).await {
613	        Ok(log_json) => log_json,
614	        Err(e) => {
615	            return MigrationPathDecision {
616	                path: MigrationPath::CannotDetermine,
617	                device_key_id: None,
618	                rotation_key_index: None,
619	                reason: format!("cannot fetch PLC audit log: {e}"),
620	            }
621	        }
622	    };
623	
624	    let rotation_keys = match current_rotation_keys_from_audit_log(&log_json) {
625	        Ok(keys) => keys,
626	        Err(e) => {
627	            return MigrationPathDecision {
628	                path: MigrationPath::CannotDetermine,
629	                device_key_id: None,
630	                rotation_key_index: None,
631	                reason: e.to_string(),
632	            }
633	        }
634	    };
635	
636	    let store = IdentityStore;
637	    let device_key_id = match store.get_or_create_device_key(did) {
638	        Ok(key) => Some(key.key_id),
639	        Err(crate::identity_store::IdentityStoreError::IdentityNotFound) => None,
640	        Err(e) => {
641	            return MigrationPathDecision {
642	                path: MigrationPath::CannotDetermine,
643	                device_key_id: None,
644	                rotation_key_index: None,
645	                reason: format!("cannot load wallet device key: {e}"),
646	            }
647	        }
648	    };
649	
650	    decide_migration_path(&rotation_keys, device_key_id.as_deref())
651	}
