653	// ── RecommendedCredentials -> typed maps ─────────────────────────────────────
654	
655	/// Convert the destination PDS's recommended `verificationMethods` (untyped JSON of
656	/// `{ id: "did:key:z..." }`) into the `BTreeMap<String, String>` that
657	/// `build_did_plc_rotation_op` expects. Requires at least the `atproto` method.
658	pub(crate) fn recommended_verification_methods(
659	    recommended: &RecommendedCredentials,
660	) -> Result<BTreeMap<String, String>, MigrateError> {
661	    let value = recommended.verification_methods.as_ref().ok_or_else(|| {
662	        MigrateError::InvalidRecommendedCredentials {
663	            message: "destination did not recommend any verificationMethods".to_string(),
664	        }
665	    })?;
666	
667	    let obj = value
668	        .as_object()
669	        .ok_or_else(|| MigrateError::InvalidRecommendedCredentials {
670	            message: "verificationMethods is not a JSON object".to_string(),
671	        })?;
672	
673	    let mut methods = BTreeMap::new();
674	    for (id, key) in obj {
675	        // Every verification method here is signed into the op, but the guard only
676	        // reasons about rotation keys — so an unexpected method would reach the
677	        // signature unchecked. A migration only ever sets the atproto method.
678	        if id != ATPROTO_VERIFICATION_METHOD_ID {
679	            return Err(MigrateError::InvalidRecommendedCredentials {
680	                message: format!(
681	                    "unexpected verificationMethods.{id}; only '{ATPROTO_VERIFICATION_METHOD_ID}' is allowed"
682	                ),
683	            });
684	        }
685	        let key_str = key
686	            .as_str()
687	            .ok_or_else(|| MigrateError::InvalidRecommendedCredentials {
688	                message: format!("verificationMethods.{id} is not a string"),
689	            })?;
690	        methods.insert(id.clone(), key_str.to_string());
691	    }
692	
693	    if !methods.contains_key(ATPROTO_VERIFICATION_METHOD_ID) {
694	        return Err(MigrateError::InvalidRecommendedCredentials {
695	            message: "destination recommended no 'atproto' verification method".to_string(),
696	        });
697	    }
698	
699	    Ok(methods)
700	}
701	
702	/// Convert the destination PDS's recommended `services` (untyped JSON of
703	/// `{ id: { type, endpoint } }`) into the `BTreeMap<String, PlcService>` that
704	/// `build_did_plc_rotation_op` expects. Requires the `atproto_pds` service.
705	pub(crate) fn recommended_services(
706	    recommended: &RecommendedCredentials,
707	) -> Result<BTreeMap<String, PlcService>, MigrateError> {
708	    let value = recommended.services.as_ref().ok_or_else(|| {
709	        MigrateError::InvalidRecommendedCredentials {
710	            message: "destination did not recommend any services".to_string(),
711	        }
712	    })?;
713	
714	    let obj = value
715	        .as_object()
716	        .ok_or_else(|| MigrateError::InvalidRecommendedCredentials {
717	            message: "services is not a JSON object".to_string(),
718	        })?;
719	
720	    let mut services = BTreeMap::new();
721	    for (id, svc) in obj {
722	        let service_type = svc.get("type").and_then(|t| t.as_str()).ok_or_else(|| {
723	            MigrateError::InvalidRecommendedCredentials {
724	                message: format!("services.{id} is missing a string 'type'"),
725	            }
726	        })?;
727	        let endpoint = svc
728	            .get("endpoint")
729	            .and_then(|e| e.as_str())
730	            .ok_or_else(|| MigrateError::InvalidRecommendedCredentials {
731	                message: format!("services.{id} is missing a string 'endpoint'"),
732	            })?;
733	        services.insert(
734	            id.clone(),
735	            PlcService {
736	                service_type: service_type.to_string(),
737	                endpoint: endpoint.to_string(),
738	            },
739	        );
740	    }
741	
742	    if !services.contains_key(ATPROTO_PDS_SERVICE_ID) {
743	        return Err(MigrateError::InvalidRecommendedCredentials {
744	            message: "destination recommended no 'atproto_pds' service".to_string(),
745	        });
746	    }
747	
748	    Ok(services)
749	}
