752	
753	/// Build the review diff for a migration op: the atproto_pds endpoint change plus the
754	/// rotation-key additions/removals implied by the swap.
755	pub(crate) fn build_migration_diff(
756	    current: &CurrentState,
757	    proposed_rotation_keys: &[String],
758	    proposed_pds_endpoint: &str,
759	) -> OpDiff {
760	    let current_set: std::collections::HashSet<&String> = current.rotation_keys.iter().collect();
761	    let proposed_set: std::collections::HashSet<&String> = proposed_rotation_keys.iter().collect();
762	
763	    let added_keys = proposed_rotation_keys
764	        .iter()
765	        .filter(|k| !current_set.contains(*k))
766	        .cloned()
767	        .collect();
768	    let removed_keys = current
769	        .rotation_keys
770	        .iter()
771	        .filter(|k| !proposed_set.contains(*k))
772	        .cloned()
773	        .collect();
774	
775	    let changed_services = vec![ServiceChange {
776	        id: ATPROTO_PDS_SERVICE_ID.to_string(),
777	        change_type: ChangeType::Modified,
778	        old_endpoint: current.pds_endpoint.clone(),
779	        new_endpoint: Some(proposed_pds_endpoint.to_string()),
780	    }];
781	
782	    OpDiff {
783	        added_keys,
784	        removed_keys,
785	        changed_services,
786	        prev_cid: Some(current.prev_cid.clone()),
787	    }
788	}
