790	// ── Imperative shell: build + submit ─────────────────────────────────────────
791	
792	/// Build and locally sign the migration identity-leg operation.
793	///
794	/// Fetches the DID's audit log (for `prev` + current state), reads the destination
795	/// PDS's recommended credentials, assembles the proposed op (device key preserved at
796	/// rotationKeys[0]), runs the strict pre-sign guard, and signs with the per-DID device
797	/// key. `dest_client` is an already-authenticated client for the DESTINATION PDS,
798	/// supplied by the migration orchestrator.
799	pub async fn build_migration_op(
800	    pds_client: &PdsClient,
801	    dest_client: &OAuthClient,
802	    did: &str,
803	) -> Result<SignedMigrationOp, MigrateError> {
804	    let store = IdentityStore;
805	
806	    // 1. Per-DID device key.
807	    let device_pub =
808	        store
809	            .get_or_create_device_key(did)
810	            .map_err(|e| MigrateError::IdentityNotFound {
811	                message: format!("failed to get device key: {e}"),
812	            })?;
813	    let device_key_id = device_pub.key_id;
814	
815	    // 2. Current audit log -> prev + current state.
816	    let log_json =
817	        pds_client
818	            .fetch_audit_log(did)
819	            .await
820	            .map_err(|e| MigrateError::NetworkError {
821	                message: format!("failed to fetch audit log: {e}"),
822	            })?;
823	    let audit_log =
824	        crypto::parse_audit_log(&log_json).map_err(|e| MigrateError::InvalidAuditLog {
825	            message: format!("failed to parse audit log: {e}"),
826	        })?;
827	    let current = latest_op_state(&audit_log)?;
828	
829	    // 3. Destination-recommended credentials.
830	    let recommended = get_recommended_did_credentials(dest_client)
831	        .await
832	        .map_err(|e| MigrateError::NetworkError {
833	            message: format!("getRecommendedDidCredentials failed: {e}"),
834	        })?;
835	
836	    // 4. Assemble the proposed op (device key forced to rotationKeys[0]).
837	    //    The destination MUST recommend at least one rotation key (its reserved
838	    //    signing key) — otherwise the op would leave the new PDS unable to act.
839	    let recommended_rotation_keys = match recommended.rotation_keys.clone() {
840	        Some(keys) if !keys.is_empty() => keys,
841	        _ => {
842	            return Err(MigrateError::InvalidRecommendedCredentials {
843	                message: "destination recommended no rotation keys".to_string(),
844	            })
845	        }
846	    };
847	    let mut proposed_rotation_keys = vec![device_key_id.clone()];
848	    for key in &recommended_rotation_keys {
849	        if key != &device_key_id {
850	            proposed_rotation_keys.push(key.clone());
851	        }
852	    }
853	    let proposed_vms = recommended_verification_methods(&recommended)?;
854	    let proposed_services = recommended_services(&recommended)?;
855	    let proposed_endpoint = proposed_services
856	        .get(ATPROTO_PDS_SERVICE_ID)
857	        .map(|s| s.endpoint.clone())
858	        .expect("recommended_services guarantees atproto_pds is present");
859	    // A migration preserves the handle: keep current alsoKnownAs.
860	    let also_known_as = current.also_known_as.clone();
861	
862	    // 5. Strict pre-sign guard — the security gate.
863	    let inputs = MigrationInputs {
864	        device_key_id: device_key_id.clone(),
865	        current_rotation_keys: current.rotation_keys.clone(),
866	        current_also_known_as: current.also_known_as.clone(),
867	        recommended_rotation_keys: recommended_rotation_keys.clone(),
868	        proposed_rotation_keys: proposed_rotation_keys.clone(),
869	        proposed_also_known_as: also_known_as.clone(),
870	        proposed_service_ids: proposed_services.keys().cloned().collect(),
871	    };
872	    guard_migration_op(&inputs)?;
873	
874	    // 6. Sign locally with the per-DID device key.
875	    let sign_closure = crate::identity_store::per_did_sign_closure(did).map_err(|e| match e {
876	        PerDidSignError::DeviceKeyNotFound { message } => {
877	            MigrateError::IdentityNotFound { message }
878	        }
879	        PerDidSignError::SigningSetupFailed { message } => MigrateError::SigningFailed { message },
880	    })?;
881	    let signed = crypto::build_did_plc_rotation_op(
882	        &current.prev_cid,
883	        proposed_rotation_keys.clone(),
884	        proposed_vms,
885	        also_known_as,
886	        proposed_services,
887	        sign_closure,
888	    )
889	    .map_err(|e| MigrateError::SigningFailed {
890	        message: format!("failed to build rotation op: {e}"),
891	    })?;
892	
893	    // 7. Diff for review.
894	    let diff = build_migration_diff(&current, &proposed_rotation_keys, &proposed_endpoint);
895	
896	    Ok(SignedMigrationOp {
897	        diff,
898	        signed_op: serde_json::from_str(&signed.signed_op_json).map_err(|e| {
899	            MigrateError::SigningFailed {
900	                message: format!("failed to parse signed op JSON: {e}"),
901	            }
902	        })?,
903	    })
904	}
