906	/// Submit the signed migration op to plc.directory and refresh the local cache.
907	/// Mirrors `recovery::submit_recovery_override`.
908	pub async fn submit_migration_op(
909	    pds_client: &PdsClient,
910	    did: &str,
911	    signed_op: &serde_json::Value,
912	) -> Result<ClaimResult, MigrateError> {
913	    let store = IdentityStore;
914	
915	    pds_client
916	        .post_plc_operation(did, signed_op)
917	        .await
918	        .map_err(|e| MigrateError::PlcDirectoryError {
919	            message: format!("plc.directory rejected the operation: {e}"),
920	        })?;
921	
922	    let updated_log =
923	        pds_client
924	            .fetch_audit_log(did)
925	            .await
926	            .map_err(|e| MigrateError::NetworkError {
927	                message: format!("failed to fetch updated audit log: {e}"),
928	            })?;
929	    store
930	        .store_plc_log(did, &updated_log)
931	        .map_err(|e| MigrateError::SigningFailed {
932	            message: format!("failed to cache updated PLC log: {e}"),
933	        })?;
934	
935	    // Fetch the PLC *data* document, not the W3C DID document: the per-identity
936	    // cache — and everything that reads it (the home card's rotationKeys[0]
937	    // custody badge, `extractPdsFromPlcDoc`'s `services` map) — expects the PLC
938	    // shape. The W3C form carries no `rotationKeys`, so caching it degrades the
939	    // badge to "Unknown".
940	    let did_doc =
941	        pds_client
942	            .fetch_plc_data_document(did)
943	            .await
944	            .map_err(|e| MigrateError::NetworkError {
945	                message: format!("failed to fetch DID document: {e}"),
946	            })?;
947	    store
948	        .store_did_doc(did, &serde_json::to_string(&did_doc).unwrap_or_default())
949	        .map_err(|e| MigrateError::SigningFailed {
950	            message: format!("failed to cache updated DID document: {e}"),
951	        })?;
952	
953	    Ok(ClaimResult {
954	        updated_did_doc: did_doc,
955	    })
956	}
