973	/// Tauri command: build + sign the migration op, parking it in `MigrationState`.
974	#[tauri::command]
975	pub async fn build_migration_op_cmd(
976	    state: tauri::State<'_, crate::oauth::AppState>,
977	    did: String,
978	) -> Result<SignedMigrationOp, MigrateError> {
979	    let dest_client = {
980	        let migration = state.migration_state.lock().await;
981	        let ms = migration
982	            .as_ref()
983	            .ok_or_else(|| MigrateError::MigrationNotReady {
984	                message: "no pending migration; destination authentication must run first"
985	                    .to_string(),
986	            })?;
987	        if ms.did != did {
988	            return Err(MigrateError::MigrationNotReady {
989	                message: format!(
990	                    "migration state DID mismatch: expected {}, got {did}",
991	                    ms.did
992	                ),
993	            });
994	        }
995	        ms.dest_oauth_client.clone()
996	    };
997	
998	    let result = build_migration_op(state.pds_client(), &dest_client, &did).await?;
999	
1000	    // Re-acquire and re-validate: a concurrent migration could have replaced the
1001	    // state while we awaited, so we must not park this DID's op into another's slot.
1002	    let mut migration = state.migration_state.lock().await;
1003	    let ms = migration
1004	        .as_mut()
1005	        .ok_or_else(|| MigrateError::MigrationNotReady {
1006	            message: "pending migration was cleared while building".to_string(),
1007	        })?;
1008	    if ms.did != did {
1009	        return Err(MigrateError::MigrationNotReady {
1010	            message: format!(
1011	                "migration state changed while building: expected {}, got {did}",
1012	                ms.did
1013	            ),
1014	        });
1015	    }
1016	    ms.signed_op = Some(result.signed_op.clone());
1017	
1018	    Ok(result)
1019	}
