1021	/// Tauri command: submit the pending migration op to plc.directory.
1022	#[tauri::command]
1023	pub async fn submit_migration_op_cmd(
1024	    state: tauri::State<'_, crate::oauth::AppState>,
1025	    did: String,
1026	) -> Result<ClaimResult, MigrateError> {
1027	    // Take (not clone) the signed op under the lock, so a concurrent or retried
1028	    // submit cannot double-post the same non-idempotent PLC operation. The
1029	    // destination client is left in place, so a failed submit can be rebuilt.
1030	    let signed_op = {
1031	        let mut migration = state.migration_state.lock().await;
1032	        let ms = migration
1033	            .as_mut()
1034	            .ok_or_else(|| MigrateError::MigrationNotReady {
1035	                message: "no pending migration to submit".to_string(),
1036	            })?;
1037	        if ms.did != did {
1038	            return Err(MigrateError::MigrationNotReady {
1039	                message: format!(
1040	                    "migration state DID mismatch: expected {}, got {did}",
1041	                    ms.did
1042	                ),
1043	            });
1044	        }
1045	        ms.signed_op
1046	            .take()
1047	            .ok_or_else(|| MigrateError::MigrationNotReady {
1048	                message: "no signed op; build the migration operation first".to_string(),
1049	            })?
1050	    };
1051	
1052	    let result = submit_migration_op(state.pds_client(), &did, &signed_op).await?;
1053	
1054	    // Migration complete — clear the state.
1055	    let mut migration = state.migration_state.lock().await;
1056	    *migration = None;
1057	
1058	    Ok(result)
1059	}
