1517	    // ── End-to-end integration (build → verify → submit) ─────────────────────
1518	    //
1519	    // Exercises the full self-signed identity leg against mock plc.directory and
1520	    // destination-PDS servers: build a repoint op, prove it verifies under the device
1521	    // key with rotationKeys[0] preserved, then submit it. Requires socket binding, so
1522	    // it is ignored in sandboxed environments (same convention as recovery.rs).
1523	    // Run with: cargo test -p identity-wallet test_build_and_submit_migration -- --ignored
1524	
1525	    #[tokio::test]
1526	    #[ignore] // Requires socket binding; ignore in sandboxed environments
1527	    async fn test_build_and_submit_migration_self_signs_repoint() {
1528	        use crate::oauth::{DPoPKeypair, OAuthSession};
1529	        use httpmock::prelude::*;
1530	        use std::sync::{Arc, Mutex};
1531	
1532	        let did = "did:plc:migratetest";
1533	        const DEST_SIGN: &str = "did:key:zDESTSIGN";
1534	
1535	        // Identity + per-DID device key (the wallet's rotationKeys[0]).
1536	        let store = IdentityStore;
1537	        let _ = store.remove_identity(did);
1538	        store.add_identity(did).expect("add_identity");
1539	        let device_pub = store
1540	            .get_or_create_device_key(did)
1541	            .expect("device key generation");
1542	        let device_key_id = device_pub.key_id.clone();
1543	
1544	        // Current audit log: the wallet already holds rotationKeys[0]; the DID points
1545	        // at the OLD PDS.
1546	        let audit_log_json = serde_json::json!([{
1547	            "did": did,
1548	            "cid": "bafy_current",
1549	            "createdAt": "2026-07-03T00:00:00Z",
1550	            "nullified": false,
1551	            "operation": {
1552	                "type": "plc_operation",
1553	                "rotationKeys": [device_key_id, OLD_PDS],
1554	                "verificationMethods": { ATPROTO_VERIFICATION_METHOD_ID: "did:key:zOLDSIGN" },
1555	                "alsoKnownAs": [HANDLE],
1556	                "services": { ATPROTO_PDS_SERVICE_ID: { "type": "AtprotoPersonalDataServer", "endpoint": "https://old.pds" } },
1557	                "prev": "bafy_prev",
1558	                "sig": "placeholder"
1559	            }
1560	        }]);
1561	
1562	        // plc.directory mock (audit log fetch, op submit, DID-doc refetch).
1563	        let plc = MockServer::start();
1564	        let audit_mock = plc.mock(|when, then| {
1565	            when.method(GET).path(format!("/{did}/log/audit"));
1566	            then.status(200)
1567	                .header("content-type", "application/json")
1568	                .json_body(audit_log_json.clone());
1569	        });
1570	        let submit_mock = plc.mock(|when, then| {
1571	            when.method(POST).path(format!("/{did}"));
1572	            then.status(200).json_body(serde_json::json!({}));
1573	        });
1574	        // The refetch must hit the PLC *data* endpoint — the cached shape needs
1575	        // `rotationKeys` (the home card's custody badge reads rotationKeys[0]).
1576	        let diddoc_mock = plc.mock(|when, then| {
1577	            when.method(GET).path(format!("/{did}/data"));
1578	            then.status(200)
1579	                .header("content-type", "application/json")
1580	                .json_body(serde_json::json!({
1581	                    "did": did,
1582	                    "alsoKnownAs": [HANDLE],
1583	                    "rotationKeys": ["did:key:zMigratedDeviceKey", DEST_SIGN],
1584	                    "verificationMethods": { "atproto": DEST_SIGN },
1585	                    "services": { "atproto_pds": { "type": "AtprotoPersonalDataServer", "endpoint": "https://new.pds" } }
1586	                }));
1587	        });
1588	        let pds_client = PdsClient::new_for_test(plc.base_url());
1589	
1590	        // Destination PDS mock: getRecommendedDidCredentials for the NEW PDS.
1591	        let dest = MockServer::start();
1592	        dest.mock(|when, then| {
1593	            when.method(GET)
1594	                .path("/xrpc/com.atproto.identity.getRecommendedDidCredentials");
1595	            then.status(200)
1596	                .header("content-type", "application/json")
1597	                .json_body(serde_json::json!({
1598	                    "rotationKeys": [DEST_SIGN],
1599	                    "alsoKnownAs": [HANDLE],
1600	                    "verificationMethods": { ATPROTO_VERIFICATION_METHOD_ID: DEST_SIGN },
1601	                    "services": { ATPROTO_PDS_SERVICE_ID: { "type": "AtprotoPersonalDataServer", "endpoint": "https://new.pds" } }
1602	                }));
1603	        });
1604	        let keypair = DPoPKeypair::get_or_create().expect("dpop keypair");
1605	        let session = Arc::new(Mutex::new(OAuthSession {
1606	            access_token: "test-access".to_string(),
1607	            refresh_token: "test-refresh".to_string(),
1608	            expires_at: u64::MAX, // never trigger a refresh
1609	            dpop_nonce: None,
1610	        }));
1611	        let dest_client =
1612	            crate::oauth_client::OAuthClient::new_for_test(keypair, session, dest.base_url());
1613	
1614	        // Build the self-signed repoint op.
1615	        let built = build_migration_op(&pds_client, &dest_client, did)
1616	            .await
1617	            .expect("build_migration_op should succeed");
1618	        audit_mock.assert();
1619	
1620	        // Diff reflects the endpoint change + key swap.
1621	        assert_eq!(built.diff.prev_cid.as_deref(), Some("bafy_current"));
1622	        assert!(built.diff.added_keys.contains(&DEST_SIGN.to_string()));
1623	        assert!(built.diff.removed_keys.contains(&OLD_PDS.to_string()));
1624	        assert_eq!(
1625	            built.diff.changed_services[0].new_endpoint.as_deref(),
1626	            Some("https://new.pds")
1627	        );
1628	
1629	        // The op verifies under the device key, and rotationKeys[0] is preserved —
1630	        // the "credible exit" guarantee, proven cryptographically.
1631	        let signed_json = serde_json::to_string(&built.signed_op).expect("serialize signed op");
